import { PostgrestClient } from '@supabase/postgrest-js';
import assert from 'node:assert/strict';
const controller=new AbortController();const invocations=[];let admittedFetches=0;
const client=new PostgrestClient('https://fixture.invalid/rest/v1',{fetch:async(url,init)=>{
 const aborted=init.signal?.aborted===true;invocations.push({method:init.method,retry:init.headers['X-Retry-Count']??null,aborted});
 if(aborted)throw init.signal.reason;
 admittedFetches++;
 return new Response(JSON.stringify({code:'',message:'Read unavailable'}),{status:503});
}});
const started=performance.now();
const pending=Promise.resolve(client.from('chat_messages').select('id').eq('id','stable-message-id').abortSignal(controller.signal).maybeSingle());
setTimeout(()=>controller.abort(new DOMException('Stopped','AbortError')),10);
const result=await pending;
assert.equal(admittedFetches,1);assert.equal(result.status,0);assert(result.error);assert.equal(controller.signal.aborted,true);
console.log(JSON.stringify({node:process.version,aborted:true,admittedFetches,fetchInvocations:invocations,resultStatus:result.status,resultError:result.error,settledAfterMs:Math.round(performance.now()-started),externalFetches:0}));
